import (
	"math/rand"
	"strings"
	"testing"
)

// checkPalindrome accepts any answer of the right length, since ties are real:
// "babad" has two longest palindromes.
func checkPalindrome(t *testing.T, s, got string, wantLen int) {
	t.Helper()
	if len(got) != wantLen {
		t.Fatalf("longestPalindrome(%q) = %q, want a palindrome of length %d", short(s), short(got), wantLen)
	}
	if !strings.Contains(s, got) {
		t.Fatalf("longestPalindrome(%q) = %q, which is not a substring", short(s), short(got))
	}
	for i, j := 0, len(got)-1; i < j; i, j = i+1, j-1 {
		if got[i] != got[j] {
			t.Fatalf("longestPalindrome(%q) = %q, which is not a palindrome", short(s), short(got))
		}
	}
}

func short(s string) string {
	if len(s) > 40 {
		return s[:40] + "..."
	}
	return s
}

func TestLongestPalindromeSmall(t *testing.T) {
	checkPalindrome(t, "babad", longestPalindrome("babad"), 3)
	checkPalindrome(t, "cbbd", longestPalindrome("cbbd"), 2)
	checkPalindrome(t, "abcda", longestPalindrome("abcda"), 1)
	checkPalindrome(t, "a", longestPalindrome("a"), 1)
	if got := longestPalindrome(""); got != "" {
		t.Fatalf("empty input: got %q, want \"\"", got)
	}
}

// TestLongestPalindromeEvenCentres is the case an odd-only expansion misses.
func TestLongestPalindromeEvenCentres(t *testing.T) {
	checkPalindrome(t, "abba", longestPalindrome("abba"), 4)
	checkPalindrome(t, "xabbay", longestPalindrome("xabbay"), 4)
	checkPalindrome(t, "aabbaa", longestPalindrome("aabbaa"), 6)
}

func bruteLongest(s string) int {
	best := 0
	for i := 0; i < len(s); i++ {
		for j := i + 1; j <= len(s); j++ {
			sub := s[i:j]
			ok := true
			for a, b := 0, len(sub)-1; a < b; a, b = a+1, b-1 {
				if sub[a] != sub[b] {
					ok = false
					break
				}
			}
			if ok && len(sub) > best {
				best = len(sub)
			}
		}
	}
	return best
}

func TestLongestPalindromeMatchesBruteForce(t *testing.T) {
	rng := rand.New(rand.NewSource(7))
	for trial := 0; trial < 300; trial++ {
		n := 1 + rng.Intn(14)
		b := make([]byte, n)
		for i := range b {
			b[i] = byte('a' + rng.Intn(3))
		}
		s := string(b)
		checkPalindrome(t, s, longestPalindrome(s), bruteLongest(s))
	}
}

// TestLongestPalindromeOnLongRunIsLinear is where expanding around every
// centre costs O(n^2): 200000 identical letters is one giant palindrome, so
// every centre expands to the edge of the string.
func TestLongestPalindromeOnLongRunIsLinear(t *testing.T) {
	const n = 200000
	s := strings.Repeat("a", n)
	if got := longestPalindrome(s); len(got) != n {
		t.Fatalf("got length %d, want %d", len(got), n)
	}
	// Half a million characters, palindromic only across the middle 'b'.
	s = strings.Repeat("a", n) + "b" + strings.Repeat("a", n)
	if got := longestPalindrome(s); len(got) != 2*n+1 {
		t.Fatalf("got length %d, want %d", len(got), 2*n+1)
	}
}

