// TestSkylineNestedPyramidIsFast builds 200000 buildings, each strictly inside
// and taller than the last. Recomputing the max over all buildings at every
// x is O(n^2) and does not finish.
func TestSkylineNestedPyramidIsFast(t *testing.T) {
	const n = 200000
	buildings := make([][]int, 0, n)
	for i := 0; i < n; i++ {
		buildings = append(buildings, []int{i, 2*n - i, i + 1})
	}
	got := getSkyline(buildings)
	if len(got) != 2*n {
		t.Fatalf("got %d key points, want %d", len(got), 2*n)
	}
	for i := 0; i < n; i++ {
		if got[i][0] != i || got[i][1] != i+1 {
			t.Fatalf("rising point %d = %v, want [%d %d]", i, got[i], i, i+1)
		}
	}
	for k := 0; k < n; k++ {
		p := got[n+k]
		wantX, wantH := n+1+k, n-1-k
		if p[0] != wantX || p[1] != wantH {
			t.Fatalf("falling point %d = %v, want [%d %d]", k, p, wantX, wantH)
		}
	}
}

